svg.script:
//
(function () {
  var svg = document.getElementById('nut-sv');
  if (!svg) return;
  var iT = svg.querySelector('#nut-it');
  var iD = svg.querySelector('#nut-id');

  var DESCS = {
    render: ['PhotoView 360 Render — Stainless Steel',
             'Studio-lit photorealistic render. Highlights hexagonal flats, bearing face, and thread-lead chamfer. Material: stainless steel 316L appearance.'],
    hex:    ['Hex Body — AF 18.29 mm',
             'Per DIN 934 M12 standard. Across-flats = 18.29 mm; circumradius R10.05 mm; nut height 11.55 mm. Modelled parametrically with driven dimensions in SolidWorks.'],
    bore:   ['M12 × 1.75 Threaded Bore',
             'Internal thread per ISO 724. Major Ø 12 mm, pitch 1.75 mm, minor Ø ≈ 10.1 mm. Ø14.5 × 90° chamfer on entry face guides fastener start.']
  };

  function reset() {
    svg.querySelectorAll('.n-ring.lit').forEach(function (r) { r.classList.remove('lit'); });
    if (iT) iT.textContent = '';
    if (iD) iD.textContent = 'Hover the drawing or render to explore the M12 nut geometry';
  }

  svg.querySelectorAll('.n-feat').forEach(function (g) {
    var id   = g.dataset.id;
    var ring = g.querySelector('.n-ring');
    function on() {
      reset();
      if (ring) ring.classList.add('lit');
      var d = DESCS[id] || ['', ''];
      if (iT) iT.textContent = d[0];
      if (iD) iD.textContent = d[1];
    }
    g.addEventListener('mouseenter', on);
    g.addEventListener('click',      on);
    g.addEventListener('mouseleave', reset);
  });

  svg.addEventListener('click', function (e) {
    if (!e.target.closest('.n-feat')) reset();
  });

  if (window.matchMedia('(prefers-reduced-motion:reduce)').matches) {
    svg.querySelectorAll('.n-ring').forEach(function (r) { r.classList.add('ready'); });
    return;
  }
  svg.querySelectorAll('.n-ring').forEach(function (r, i) {
    setTimeout(function () { r.classList.add('ready'); }, 500 + i * 600);
  });
})();
//
